import { delegate, type SafeHtml } from 'kerfjs';
import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import '@kerfjs/ui/layout.css';
import './view-toolbar.css';

export type WorkspaceView = 'board' | 'list' | 'timeline';
export type WorkspaceAction = { type: 'workspace.set-view'; value: WorkspaceView };
const choices = [
  { value: 'board', label: 'Board' },
  { value: 'list', label: 'List' },
  { value: 'timeline', label: 'Timeline' },
];
export function ViewToolbar({ value }: { value: WorkspaceView }) {
  return <div class="view-toolbar kui-layout">
    <Toolbar label="Workspace view" leading={<ToolbarText text="Tasks" size="small" />}
      trailing={<ToolbarControlGroup label="Workspace presentation">
        <SegmentedControl id="workspace-view" label="View" action="workspace.set-view"
          value={value} choices={choices} appearance="toolbar" size="small" />
      </ToolbarControlGroup>} />
  </div>;
}
export function mountViewToolbar(root: HTMLElement, app: {
  getView(): WorkspaceView;
  dispatch(action: WorkspaceAction): void;
  subscribe(listener: () => void): () => void;
  renderInto(root: HTMLElement, view: SafeHtml): void;
}) {
  const render = () => app.renderInto(root, <ViewToolbar value={app.getView()} />);
  render();
  const unsubscribe = app.subscribe(render);
  const dispose = delegate(root, 'click', '[data-action="workspace.set-view"]', (_event, element) => {
    const value = (element as HTMLElement).dataset.segmentValue;
    if (value !== 'board' && value !== 'list' && value !== 'timeline') return;
    if (value !== app.getView()) app.dispatch({ type: 'workspace.set-view', value });
  });
  // The application's reducer updates its controlled view and notifies subscribers.
  // All enabled segment buttons remain tabbable; native Enter/Space activates them.
  return () => { dispose(); unsubscribe(); };
}
